INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
  ('b0000000-0000-0000-0019-000000000000', '배열(Array)과 연결 리스트(Linked List)의 차이점을 설명하세요.', 'EASY', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000001', '스택(Stack)과 큐(Queue)는 각각 어떤 구조이고 어떻게 동작하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000002', '트리(Tree) 자료구조란 무엇이며, 이진 트리(Binary Tree)의 특징은?', 'EASY', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000003', '이진 탐색 트리(BST)의 속성과 이점은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000004', '힙(Heap) 자료구조는 무엇이며 어떤 종류가 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000005', '최대 힙(Max Heap)과 최소 힙(Min Heap)의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000006', '그래프(Graph)란 무엇이며, 트리와 어떻게 다른가요?', 'EASY', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000007', '인접 리스트와 인접 행렬로 그래프를 표현하는 방법의 차이는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000008', 'BFS와 DFS를 자료구조 측면에서 비교하면 무엇이 다른가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000009', '해시 테이블(Hash Table)은 어떤 원리로 동작하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000010', '해시 테이블에서 해시 충돌(collision)은 무엇이며 해결 방법은?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000011', '체이닝(Chaining)과 오픈 어드레싱(Open Addressing)의 차이는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000012', '트라이(Trie) 자료구조는 무엇이며, 어디에 활용되나요?', 'HARD', 'b0000000-0000-0000-0000-000000000019'),
  ('b0000000-0000-0000-0019-000000000013', '이중 연결 리스트(Double Linked List)의 특징은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000019');
